use std::io::{self, Write};
use unisphere_cli::{run_adapters, CliContext};
struct Faulty { fail_flush: bool, bytes: Vec<u8> }
impl Write for Faulty {
 fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
  if !self.fail_flush { return Err(io::Error::other("SYNTHETIC-PRIVATE-IO")); }
  self.bytes.extend_from_slice(bytes); Ok(bytes.len())
 }
 fn flush(&mut self) -> io::Result<()> { Err(io::Error::other("SYNTHETIC-PRIVATE-IO")) }
}
fn main() {
 let context = CliContext { cwd: "/unused".into(), stdout_is_terminal: false, version: "smoke".into() };
 for fail_flush in [false, true] {
  let mut output = Faulty { fail_flush, bytes: Vec::new() };
  let mut errors = Vec::new();
  let args = ["unisphere", "adapters", "list", "--json"].map(Into::into).to_vec();
  assert_eq!(run_adapters(args, &context, &[], &mut output, &mut errors), 1);
  assert!(!String::from_utf8(errors).unwrap().contains("SYNTHETIC-PRIVATE-IO"));
 }
 println!("Actual embedded catalog: write and flush failures return exit 1; private I/O detail is not emitted.");
}
